// Pointer-chase latency microbenchmark for Kunpeng 920 / TaiShan v110.
// Usage: ./lat <working_set_bytes> <iterations>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ull + ts.tv_nsec;
}

int main(int argc, char **argv) {
    size_t bytes = strtoull(argv[1], 0, 0);
    uint64_t iters = argc > 2 ? strtoull(argv[2], 0, 0) : (1ull << 22);
    size_t n = bytes / 64;               // one pointer per 64B line
    uint64_t *p = aligned_alloc(64, n * 64);
    // random permutation chase
    for (size_t i = 0; i < n; i++) p[i * 8] = i * 64;
    uint64_t seed = 0x9e3779b97f4a7c15ull;
    for (size_t i = n - 1; i > 0; i--) {
        seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17;
        size_t j = (size_t)(seed % (i + 1));
        uint64_t t = p[i * 8]; p[i * 8] = p[j * 8]; p[j * 8] = t;
    }
    // convert to pointer offsets
    for (size_t i = 0; i < n; i++) p[i * 8] = p[i * 8] / 64 * 64; // keep as byte offset
    volatile uint64_t sink = 0;
    // warm up
    uint64_t idx = 0;
    for (size_t i = 0; i < 1024; i++) idx = *(uint64_t *)((char *)p + idx);
    uint64_t t0 = now_ns();
    for (uint64_t i = 0; i < iters; i++) idx = *(uint64_t *)((char *)p + idx);
    uint64_t t1 = now_ns();
    sink = idx;
    double ns_per = (double)(t1 - t0) / iters;
    printf("%zu %zu %.2f\n", bytes, n, ns_per);
    (void)sink;
    return 0;
}
